-- Seed the existing devlog entries as published (idempotent by slug).
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-02-62137', 'a-marketplace-for-skills-and-tools-2026-11-02', '2026-11-02', 'imagoro', 'A marketplace for skills and tools', 'The site gained a Skills & Tools page with search, filters and rankings. Vault Memory is the first entry: an MCP server and agent skill that give agents a shared Obsidian notebook.', 'Imagoro', 'published', '2026-11-02T00:00:00.000Z', '2026-11-02T00:00:00.000Z', '2026-11-02T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-31-16118', 'kao-survives-losing-its-engine-2026-10-31', '2026-10-31', 'imagoro', 'Kao survives losing its engine', 'If the heavy model goes down, Kao drops to a smaller local model and returns on its own once the engine is back. Only outages fail over. A refusal from the gate stays a refusal, so failing over can''t be used to get around the content rules.', 'Imagoro', 'published', '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-31-19664', 'every-model-path-goes-through-a-gate-2026-10-31', '2026-10-31', 'lab', 'Every model path goes through a gate', 'All of Kao''s engine traffic now passes through the gate, including the fallback route, so it follows the same rules as the primary one. Key auth also reached the last open engine, and model digests are still verified through the gates.', 'Imagoro', 'published', '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-30-94025', 'the-console-gets-prompts-and-a-security-view-2026-10-30', '2026-10-30', 'imagoro', 'The console gets prompts and a security view', 'The Harness Console can now send prompts through the gate under its own key, and it shows the Security Suite''s decisions and findings. That view is read-only and its text is treated as untrusted. Controls stay in the Security Console.', 'Imagoro', 'published', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-30-39388', 'a-watchdog-for-the-inference-engine-2026-10-30', '2026-10-30', 'lab', 'A watchdog for the inference engine', 'A small watchdog now checks the engine and its gate, and repairs only the part that failed. It never restarts something stopped on purpose, and it gives up after three repairs in an hour rather than fighting a problem that needs a person.', 'Imagoro', 'published', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-30-23385', 'one-site-one-build-2026-10-30', '2026-10-30', 'imagoro', 'One site, one build', 'The portfolio and the browser terminal now ship as a single build on imagoro.net. The terminal loads on demand, so most visitors never download it.', 'Imagoro', 'published', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-30-59798', 'back-to-planets-2026-10-30', '2026-10-30', 'voxel', 'Back to planets', 'With the overhaul merged, work is returning to planetary rendering and lasting destruction. The next goal is a stress test: render a planet, hit it with a scripted projectile, and keep the damage.', 'Imagoro', 'published', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-29-91657', 'readable-logs-and-a-clean-cold-start-2026-10-29', '2026-10-29', 'security', 'Readable logs, and a clean cold start', 'The suite''s records now appear as readable notes, rendered every 15 minutes. The whole lab also came back on its own after a full power-down.', 'Imagoro', 'published', '2026-10-29T00:00:00.000Z', '2026-10-29T00:00:00.000Z', '2026-10-29T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-28-46963', 'vllm-on-an-rdna-4-card-under-wsl-2026-10-28', '2026-10-28', 'lab', 'vLLM on an RDNA 4 card, under WSL', 'The heavy tier now runs Qwen3-8B-AWQ on vLLM, on a Radeon RX 9060 XT inside WSL2. Getting there took a card-specific container and a bridge for AMD''s WSL tooling. It''s only reachable through a keyed gate.', 'Imagoro', 'published', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-28-34338', 'keys-instead-of-ip-lists-2026-10-28', '2026-10-28', 'lab', 'Keys instead of IP lists', 'Engines moved to loopback behind a gate with per-client keys and model lists. Addresses change, so they were never a good identity. Heavy models also moved off the small agent box and onto the workstation''s 16 GB card.', 'Imagoro', 'published', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-28-25632', 'the-gate-learns-to-tell-evidence-from-attacks-2026-10-28', '2026-10-28', 'security', 'The gate learns to tell evidence from attacks', 'The gate went from a scaffold to a working proxy with client keys, model allowlists and content rules. A security tool has to read hostile text as evidence without following it, so the rules separate the two.', 'Imagoro', 'published', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-28-39867', 'reasoning-off-has-to-mean-off-2026-10-28', '2026-10-28', 'security', 'Reasoning off has to mean off', 'About one security cycle in six was failing with an empty model response. The crew framework was replacing the system message that turned reasoning off, so the setting never reached the model.', 'Imagoro', 'published', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z', '2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-27-10256', 'the-suite-can-act-behind-four-locks-2026-10-27', '2026-10-27', 'security', 'The suite can act, behind four locks', 'An operator console signs every request, and a guarded executor needs four independent locks before it will apply a countermeasure. Evals now show a model is good enough before it''s trusted.', 'Imagoro', 'published', '2026-10-27T00:00:00.000Z', '2026-10-27T00:00:00.000Z', '2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-27-35870', 'the-security-suite-goes-live-2026-10-27', '2026-10-27', 'security', 'The security suite goes live', 'The lab now audits itself. Collectors post redacted events to a shared blackboard, and every 30 minutes a crew of eight local models turns them into findings and a decision.', 'Imagoro', 'published', '2026-10-27T00:00:00.000Z', '2026-10-27T00:00:00.000Z', '2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-19-28303', 'the-engine-overhaul-lands-2026-10-19', '2026-10-19', 'voxel', 'The engine overhaul lands', 'A twelve-phase overhaul merged, bringing the planetary code and lasting destruction into the main line along with a single unified UI.', 'Imagoro', 'published', '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-16-34948', 'a-determinism-bug-bisected-2026-10-16', '2026-10-16', 'voxel', 'A determinism bug, bisected', 'Stress runs were giving different fingerprints, and it looked like load. It was a real bug: animation poses were feeding the simulation''s eye, and so the shot origin. With view state kept out of the simulation, the fingerprint matches at any frame rate.', 'Imagoro', 'published', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-16-51659', 'the-ui-foundations-2026-10-16', '2026-10-16', 'imagoro', 'The UI foundations', 'The UI ecosystem reached its M6 milestone: a block spec, a React renderer with 12 block families, a node canvas, a desktop shell, and an access matrix shared with the server.', 'Imagoro', 'published', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-16-40186', 'hazards-without-coordinates-2026-10-16', '2026-10-16', 'nav', 'Hazards without coordinates', 'Clients no longer send GPS. They ask for coarse map cells of about 40 by 20 km, and the hub refuses coordinates by default. Hazard data comes from weather, work zone and traffic feeds, and each event is signed.', 'Imagoro', 'published', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z', '2026-10-16T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-10-09-56451', 'a-terminal-in-the-browser-2026-10-09', '2026-10-09', 'imagoro', 'A terminal in the browser', 'The browser terminal began as an xterm UI with a demo mode that needs no backend, so anyone can try it without reaching a real machine.', 'Imagoro', 'published', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z', '2026-10-09T00:00:00.000Z');
